        for p in self.alphabet:
            n.addTransition(len(ph)+1, p, len(ph)+1)

        return n.toDFA()

    def and_(self, items):
        # intersect
        dfa = items[0] & items[1]
        return dfa.minimal()

    def or_(self, items):
        # union
        dfa = items[0] | items[1]
        return dfa.minimal()

    def ph(self, items):
        return items

    def IDENT(self, tok):
        return str(tok)

    def NEWLINE(self, tok):
        return "NEWLINE"

    def transform_with_alphabet(self, tree, alphabet):
        # set alphabet to all DFAs
        self.alphabet = alphabet
