grammar = r"""
    start: policy";" (NEWLINE policy";")* NEWLINE?

    policy: predicate action              -> policy

    // -------- predicates --------
    ?predicate: "(" predicate "and" predicate  ")" -> and_
        |     | "(" predicate "or"  predicate  ")"  -> or_
