import os
import sys

# Reuse the full policy-language compiler in ../compiler (grammar, predicate/DFA
# construction, and union/intersection ops). We only replace its parallel
# tree-reduction with a serial merge so the eBPF agent never spawns processes.
_COMPILER_DIR = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", "compiler"))
if _COMPILER_DIR not in sys.path:
    sys.path.insert(0, _COMPILER_DIR)

from lark import Lark
import compiler as C

POLICY_DIR = "ebpf/access_control/"

_parser = Lark(C.grammar, start="start")


class _SerialDFATransformer(C.DFATransformer):
    """Same semantics as compiler.DFATransformer, but merges policies serially
    (deny-by-default: union the ALLOW DFAs, intersect the complemented DROP DFAs,
    then intersect the two). Avoids the ProcessPool used for large-scale compiles."""

    def start(self, items):
        allow = [x[0] for x in items if x != "NEWLINE" and x[1] == "ALLOW"]
        drop = [x[0] for x in items if x != "NEWLINE" and x[1] == "DROP"]
        allow_dfa = C.union(allow) if allow else None
        drop_dfa = C.intersection(drop) if drop else None
        if allow_dfa and drop_dfa:
            return (allow_dfa & drop_dfa).minimal()
        elif allow_dfa:
            return allow_dfa
        else:
            raise Exception("All policies are DROP, no ALLOW policy found.")


def _compile(text, registry):
    tree = _parser.parse(text)
    alphabet = {s["name"] for s in registry}
    return _SerialDFATransformer().transform_with_alphabet(tree, alphabet)


def create(text, registry):
    dfa = _compile(text, registry)
    delta = dict(dfa.delta)
    useful = set(dfa.usefulStates())
    if dfa.Initial not in useful:
        raise ValueError("policy accepts no request path")

    def name(i):
        return "START" if i == dfa.Initial else f"q{i}"

    states = [name(i) for i in sorted(useful) if i != dfa.Initial]
    transitions = {}
    for s in useful:
        for symbol, target in delta.get(s, {}).items():
            if target not in useful:
                continue
            transitions.setdefault(name(s), {})[symbol] = name(target)
    order = [dfa.Initial] + [i for i in sorted(useful) if i != dfa.Initial]
    index = {i: n for n, i in enumerate(order)}
    names = [s['name'] for s in sorted(registry, key=lambda s: s['label'])]
    image = {'accept': [i in dfa.Final for i in order],
             'rows': [[index.get(delta.get(i, {}).get(a), 4294967295) for a in names] for i in order]}
    return image
"""CPU map backend. Extend Agent to the full public lifecycle contract."""
import ctypes
from .create_dfa import create

class MemoryMap:
    def __init__(self): self.entries={}
    def __setitem__(self,key,value): self.entries[(key.st,key.t)]=value.value

class Agent:
    def __init__(self,services,limits):
        self.NAME_TO_LABEL={s['name']:s['label'] for s in services}
        self.services=services;self.limits=limits
        self.B={'access_control':MemoryMap()};self.images={};self.active=None

    def insert_multihop_policy(self,epoch,text):
        access_control_map=self.B['access_control']
        image=create(text,self.services)
        initial_state='START'
        states=['q'+str(i) for i in range(1,len(image['rows']))]
        def state_index(name):
            return 0 if name == "START" else states.index(name) + 1

        names = [s['name'] for s in sorted(self.services, key=lambda s: s['label'])]
        transitions = {}
        for i, row in enumerate(image['rows']):
            source = initial_state if i == 0 else states[i-1]
            transitions[source] = {
                name: (initial_state if target == 0 else states[target-1])
                for name, target in zip(names, row) if target != 4294967295
            }
        NAME_TO_LABEL = self.NAME_TO_LABEL

        class KeyT(ctypes.Structure):
            _fields_ = [("st", ctypes.c_uint32), ("t", ctypes.c_uint32)]

        for k, v in transitions.items():
            for inp, next_state in v.items():
                key = KeyT()
                key.st = state_index(k)
                key.t = NAME_TO_LABEL[inp]
                value = ctypes.c_uint32(state_index(next_state))
                access_control_map[key] = value

        self.images[epoch]=image
        return {'ok':True,'epoch':epoch,'image':image}

    def event(self,event):
        try:
            if event['op']=='stage':return self.insert_multihop_policy(event['epoch'],event['policy'])
            if event['op']=='commit' and event['epoch'] in self.images:
                self.active=event['epoch'];return {'ok':True}
            # Lifecycle operations and atomic capacity/version handling are unfinished.
            return {'error':'rejected'}
        except Exception:return {'error':'rejected'}

