    for i in range(ns):
        node = state_node[i]
        ok = node in allow_nodes or ((complex_allow >> i) & 1)
        bad = node in drop_nodes or ((complex_drop >> i) & 1)
        if ok and not bad:
            accept[i] = 1

    def empty_image():
        row = [DENY] * ncols
        return {'accept': [False], 'rows': [row]}, 0

    if not any(accept):
        return empty_image()

    # ---- live states: can reach an accepting state ----
    rev = [[] for _ in range(ns)]
    for i in range(ns):
        row = state_trans[i]
        for c in range(ncols):
            rev[row[c]].append(i)
    live = bytearray(ns)
    stack = [i for i in range(ns) if accept[i]]
    for i in stack:
        live[i] = 1
    while stack:
        j = stack.pop()
        for p in rev[j]:
            if not live[p]:
                live[p] = 1
                stack.append(p)

    live_list = [i for i in range(ns) if live[i]]
    live_index = {}
    for new, old in enumerate(live_list):
        live_index[old] = new
    L = len(live_list)

    # ---- Moore partition refinement on live states + dead sink class ----
    class_of = [1 if accept[old] else 0 for old in live_list]
    nclass = max(class_of) + 1
    while True:
        sig_map = {}
        new_class = [0] * L
        for new in range(L):
            old = live_list[new]
            row = state_trans[old]
            tgt = []
            for c in range(ncols):
                tn = live_index.get(row[c], -1)
                tgt.append(class_of[tn] if tn >= 0 else -1)
            sig = (class_of[new], tuple(tgt))
            cid = sig_map.get(sig)
            if cid is None:
                cid = len(sig_map)
                sig_map[sig] = cid
            new_class[new] = cid
        if len(sig_map) == nclass:
            break
        class_of = new_class
        nclass = len(sig_map)

    class_rep = [0] * nclass
    for new in range(L):
        class_rep[class_of[new]] = live_list[new]

    # ---- BFS numbering of the retained classes from START ----
    start_cls = class_of[live_index[0]]
    order = [start_cls]
    idx = {start_cls: 0}
    head = 0
    while head < len(order):
        c = order[head]
        head += 1
        row = state_trans[class_rep[c]]
        for col in range(ncols):
            tn = live_index.get(row[col], -1)
            if tn < 0:
                continue
            tc = class_of[tn]
            if tc not in idx:
                idx[tc] = len(order)
                order.append(tc)

    rows = []
    accept_out = []
    for c in order:
        row = state_trans[class_rep[c]]
        out_row = []
        for col in range(ncols):
            tn = live_index.get(row[col], -1)
            if tn < 0:
                out_row.append(DENY)
            else:
                tc = class_of[tn]
                out_row.append(idx[tc] if tc in idx else DENY)
        rows.append(out_row)
        accept_out.append(bool(accept[class_rep[c]]))

    cells = sum(1 for row in rows for t in row if t != DENY)
    if len(rows) > 8192:
        raise PolicyError('rows')
    return {'accept': accept_out, 'rows': rows}, cells
