"""Independent brute-force semantics oracle for policy language checks."""
import itertools, sys
sys.path.insert(0, '/workspace/tests')
from harness import run_cli, req, job

DENY = 4294967295

def eval_pred(pred, word):
    kind = pred[0]
    if kind == 'match':
        return tuple(word) == pred[1]
    if kind == 'startswith':
        p = pred[1]
        return tuple(word[:len(p)]) == p
    if kind == 'endswith':
        p = pred[1]
        return tuple(word[-len(p):]) == p if len(p) else True
    if kind == 'contains':
        p = pred[1]
        n = len(p)
        if n == 0:
            return True
        return any(tuple(word[i:i+n]) == p for i in range(len(word) - n + 1))
    if kind == 'not':
        return not eval_pred(pred[1], word)
    if kind == 'and':
        return eval_pred(pred[1], word) and eval_pred(pred[2], word)
    return eval_pred(pred[1], word) or eval_pred(pred[2], word)

def allowed(rules, word):
    has_allow = False
    for pred, act in rules:
        if eval_pred(pred, word):
            if act == 'drop':
                return False
            has_allow = True
