        for combo in itertools.product(names, repeat=length):
            want = allowed(rules, combo)
            got = dfa_accepts(image, names, combo, name_to_col)
            if want != got:
                print(f"[FAIL] {name}: word {combo} want {want} got {got}")
                bad += 1
                if bad > 5:
                    return False
    # structural: BFS numbering + minimality of the image
    ok = check_structure(name, image, len(labels))
    if ok and not bad:
        print(f"[ok] {name}")
    return ok and not bad

def check_structure(name, image, ncols):
    rows = image['rows']
    accept = image['accept']
    n = len(rows)
    assert all(len(r) == ncols for r in rows), f"{name}: bad row width"
    assert all(type(a) is bool for a in accept), f"{name}: accept not bool"
    # every target is valid index or DENY
    for r in rows:
        for t in r:
            assert t == DENY or (type(t) is int and 0 <= t < n), f"{name}: bad target {t}"
    # BFS numbering: state 0 = START; discovery order by cols ignoring DENY
    disc = [0]
    seen = {0}
    for s in disc:
        for c in range(ncols):
            t = rows[s][c]
            if t != DENY and t not in seen:
                seen.add(t)
                disc.append(t)
    if disc != list(range(n)):
        print(f"[FAIL] {name}: not BFS-numbered: {disc}")
        return False
    # BFS discovery order must follow increasing column order:
    idx = 1
    for s in disc:
        for c in range(ncols):
            t = rows[s][c]
            if t != DENY and t != s:
                pass
    # recompute strict BFS discovery numbering
    order = [0]
    seen = {0}
    head = 0
    expected_index = {}
    expected_index[0] = 0
    while head < len(order):
        s = order[head]; head += 1
        for c in range(ncols):
            t = rows[s][c]
            if t != DENY and t not in seen:
                seen.add(t)
                expected_index[t] = len(order)
                order.append(t)
    if order != list(range(n)):
        print(f"[FAIL] {name}: BFS order mismatch {order}")
        return False
    # minimality: no two states with identical residuals (table filling on image + dead)
    # states: 0..n-1 plus DEAD; transitions DENY -> DEAD
    N = n + 1
    DEAD = n
    T = [[rows[i][c] if rows[i][c] != DENY else DEAD for c in range(ncols)] for i in range(n)]
    T.append([DEAD]*ncols)
    acc = [a for a in accept] + [False]
    dist = [[False]*N for _ in range(N)]
    for i in range(N):
        for j in range(i+1, N):
            if acc[i] != acc[j]:
                dist[i][j] = dist[j][i] = True
    changed = True
    while changed:
        changed = False
        for i in range(N):
            for j in range(i+1, N):
                if dist[i][j]:
                    continue
                for c in range(ncols):
                    a, b = T[i][c], T[j][c]
                    if a != b and (dist[a][b] or a == b):
                        pass
                    if a != b and dist[a][b]:
                        dist[i][j] = dist[j][i] = True
                        changed = True
                        break
    for i in range(n):
        for j in range(i+1, n):
            if not dist[i][j]:
                print(f"[FAIL] {name}: states {i},{j} not distinguishable (not minimal)")
                return False
    # dead residual removed: no row may be a pure dead row
    for i in range(n):
        row_dead = all(t == DENY for t in rows[i])
        reaches_accept = acc[i]
        # check reachability of accept
        reach = False
        stack = [i]
        vis = {i}
        while stack:
            s = stack.pop()
            if acc[s]:
                reach = True
                break
            for t in rows[s]:
                if t != DENY and t not in vis:
                    vis.add(t)
                    stack.append(t)
        if not reach:
            print(f"[FAIL] {name}: state {i} cannot reach accept (dead residual retained)")
            return False
    return True
