random.seed(20240611)
SVC = [{"name": n, "label": (i * 5 + 3) % 16 + 1} for i, n in enumerate("ABCDE")]
NAMES = ["A", "B", "C", "D", "E"]

def rand_path(maxlen):
    n = random.randint(0, maxlen)
    return tuple(random.choice(NAMES) for _ in range(n))

def rand_pred(depth, budget):
    """Random predicate tree within declared bounds; budget = atom count."""
    if depth <= 1 or budget <= 1 or random.random() < 0.4:
        kind = random.choice(["match", "match", "startswith", "endswith", "contains"])
        return (kind, rand_path(4 if kind != "match" else 6))
    if random.random() < 0.25:
        return ("not", rand_pred(depth - 1, budget))
    left_budget = random.randint(1, budget - 1)
    return (random.choice(["and", "or"]),
            rand_pred(depth - 1, left_budget),
            rand_pred(depth - 1, budget - left_budget))

def atoms_of(pred):
    if pred[0] in ("match", "startswith", "endswith", "contains"):
        return 1
    if pred[0] == "not":
        return atoms_of(pred[1])
    return atoms_of(pred[1]) + atoms_of(pred[2])

def nonmatch_of(pred, acc):
    if pred[0] in ("startswith", "endswith", "contains"):
        acc.add((pred[0], pred[1]))
    elif pred[0] == "not":
        nonmatch_of(pred[1], acc)
    elif pred[0] in ("and", "or"):
        nonmatch_of(pred[1], acc)
        nonmatch_of(pred[2], acc)

def show(pred):
    if pred[0] == "match":
        return f"match({','.join(pred[1])})"
    if pred[0] in ("startswith", "endswith", "contains"):
        return f"{pred[0]}({','.join(pred[1])})"
    if pred[0] == "not":
        return f"not({show(pred[1])})"
    return f"({show(pred[1])} {pred[0]} {show(pred[2])})"

def gen_policy():
    rules = []
    complex_used = 0
    nm_all = set()
    for _ in range(random.randint(1, 6)):
        is_simple = random.random() < 0.5
        if is_simple:
            pred = ("match", rand_path(6))
        else:
            if complex_used >= 8:
                continue
            while True:
                pred = rand_pred(random.randint(2, 5), random.randint(2, 10))
                if atoms_of(pred) <= 32:
